using System.Text.RegularExpressions;
using Bunit;
using FluentCMS.Admin.Components.Icons;
using Microsoft.AspNetCore.Components;

namespace FluentCMS.Tests.Admin;

// The icon components are generated by Icons.targets from the pinned Lucide release and committed; these tests keep the
// list, the generated files, the pin and the licence in step.
public sealed partial class IconsTests
{
    private static readonly string Admin = Path.Combine(ProjectReferenceRulesTests.FindRepositoryRoot(), "src", "FluentCMS.Admin");

    private static readonly string[] Listed = File.ReadAllLines(Path.Combine(Admin, "Icons", "icons.txt"))
        .Select(line => line.Trim())
        .Where(line => line.Length > 0 && !line.StartsWith('#'))
        .ToArray();

    private static readonly Type[] Generated = typeof(XIcon).Assembly.GetTypes()
        .Where(type => type.Namespace == typeof(XIcon).Namespace && typeof(IComponent).IsAssignableFrom(type))
        .ToArray();

    public static TheoryData<string> Names => new(Listed);

    [Fact]
    public void Every_listed_icon_has_a_component_and_every_component_is_listed()
    {
        var expected = Listed.Select(TypeName).Order(StringComparer.Ordinal);
        var files = Directory.EnumerateFiles(Path.Combine(Admin, "Components", "Icons"), "*.razor").Select(Path.GetFileNameWithoutExtension).Order(StringComparer.Ordinal);

        Assert.NotEmpty(Listed);
        Assert.Equal(expected, files);
        Assert.Equal(expected, Generated.Select(type => type.Name).Order(StringComparer.Ordinal));
    }

    [Fact]
    public void Every_component_was_generated_from_the_pinned_version()
    {
        var targets = File.ReadAllText(Path.Combine(Admin, "Icons.targets"));
        var version = VersionRegex().Match(targets).Groups[1].Value;

        Assert.Matches(@"^\d+\.\d+\.\d+$", version);
        Assert.Matches("<_LucideArchiveSha256>[0-9a-f]{64}</_LucideArchiveSha256>", targets);
        Assert.Matches("<_LucideLicenseSha256>[0-9a-f]{64}</_LucideLicenseSha256>", targets);
        Assert.All(Listed, name => Assert.StartsWith(
            $"@* Lucide \"{name}\" {version}, generated by Icons.targets",
            File.ReadAllText(Path.Combine(Admin, "Components", "Icons", TypeName(name) + ".razor"))));
    }

    [Fact]
    public void The_licence_of_the_pinned_release_is_next_to_the_list()
    {
        var licence = File.ReadAllText(Path.Combine(Admin, "Icons", "LICENSE"));

        Assert.StartsWith("ISC License", licence);
        Assert.Contains("Lucide Icons and Contributors", licence);
        Assert.Contains("The MIT License (MIT) (for the icons listed above)", licence);
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Each_icon_renders_lucides_svg_hidden_from_assistive_technology(string name)
    {
        using var context = new AdminTestContext();
        var type = Generated.Single(candidate => candidate.Name == TypeName(name));

        var cut = context.Render<DynamicComponent>(dynamic => dynamic
            .Add(d => d.Type, type)
            .Add(d => d.Parameters, new Dictionary<string, object> { ["Class"] = "size-4" }));
        var svg = cut.Find("svg");

        Assert.Equal("0 0 24 24", svg.GetAttribute("viewBox"));
        Assert.Equal("none", svg.GetAttribute("fill"));
        Assert.Equal("currentColor", svg.GetAttribute("stroke"));
        Assert.Equal("2", svg.GetAttribute("stroke-width"));
        Assert.Equal("true", svg.GetAttribute("aria-hidden"));
        Assert.Equal(["lucide", "lucide-" + name, "size-4"], svg.ClassList);
        Assert.NotEmpty(svg.Children);
    }

    [Fact]
    public void Attributes_override_the_defaults_so_an_icon_can_be_bolder_or_named()
    {
        using var context = new AdminTestContext();

        var svg = context.Render<CheckIcon>(icon => icon
            .AddUnmatched("stroke-width", "3")
            .AddUnmatched("aria-hidden", "false")
            .AddUnmatched("aria-label", "Done")
            .AddUnmatched("role", "img")).Find("svg");

        Assert.Equal("3", svg.GetAttribute("stroke-width"));
        Assert.Equal("false", svg.GetAttribute("aria-hidden"));
        Assert.Equal("Done", svg.GetAttribute("aria-label"));
        Assert.Equal("img", svg.GetAttribute("role"));
    }

    private static string TypeName(string name) => string.Concat(name.Split('-').Select(part => char.ToUpperInvariant(part[0]) + part[1..])) + "Icon";

    [GeneratedRegex("<LucideVersion>([^<]+)</LucideVersion>")]
    private static partial Regex VersionRegex();
}
